"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * DONUT CHART: parts of a whole as a ring or a half-ring gauge
 *
 *   arrive    the first time it's on screen each slice draws
 *             round from where it starts, one after another,
 *             and the total rolls up from zero
 *   point     point at a slice (or its legend row) and it
 *             thickens while the others step back; the centre's
 *             label morphs to the slice's name and the figure
 *             rolls from the total to its value, with its share
 *             opening underneath
 *   toggle    a legend row hides or shows its slice: the others
 *             slide round to close the gap and every share and
 *             the total roll to the new sums
 *   data      new numbers (another month) slide every slice to
 *             its new place instead of redrawing
 *   max       given a max, the slices fill only their share of
 *             it and the rest of the track stays empty: budget
 *             spent, storage used
 *
 * Each slice is one circle's stroke: its length and where it
 * starts are stroke-dasharray and stroke-dashoffset, so a CSS
 * transition carries every change. The legend is the accessible
 * part (buttons that show and hide slices); the ring is drawn
 * for the eye only.
 * ───────────────────────────────────────────────────────── */

export interface DonutSlice {
  id: string;
  label: string;
  value: number;
  /** Any CSS colour; slices without one take --chart-1 to --chart-5 in order. */
  color?: string;
}

export interface DonutChartProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  data: DonutSlice[];
  /** A full ring, or a half-ring gauge read from left to right. */
  variant?: "donut" | "gauge";
  /** What a full ring stands for. With it the slices fill only their share and the rest of the track stays empty. */
  max?: number;
  title?: React.ReactNode;
  description?: React.ReactNode;
  /** Beside the title, e.g. a period switch. */
  action?: React.ReactNode;
  /** Above the figure in the centre while nothing is pointed at. */
  centerLabel?: string;
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  /** Ring thickness in px, at the ring's full size. */
  thickness?: number;
  /** Ids of the slices taken out, controlled or not. */
  hiddenSlices?: string[];
  defaultHiddenSlices?: string[];
  onHiddenSlicesChange?: (hidden: string[]) => void;
  /** Show the legend (which also shows and hides slices). */
  legend?: boolean;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const PALETTE = [
  "var(--chart-1, var(--primary))",
  "var(--chart-2, #e8743b)",
  "var(--chart-3, #1baf7a)",
  "var(--chart-4, #8b6fe8)",
  "var(--chart-5, #e0a21b)",
];
const NONE: string[] = [];
const SIZE = 200;
/** How much a pointed-at slice thickens, in px; the ring leaves room for it. */
const GROW = 5;
/** The gap between two slices, in px along the ring. */
const GAP = 3.5;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );
const subscribeNothing = () => () => {};
/** Text in the visitor's locale waits for hydration, so the server's en-US render and the first client render match. */
const useHydrated = () =>
  React.useSyncExternalStore(
    subscribeNothing,
    () => true,
    () => false,
  );

/** Past the fifth slice, colours repeat a step darker so neighbours never match. */
const colorOf = (slice: DonutSlice, i: number) =>
  slice.color ??
  (i < PALETTE.length
    ? PALETTE[i]
    : `color-mix(in oklab, ${PALETTE[i % PALETTE.length]} 70%, var(--foreground))`);

export function DonutChart({
  data,
  variant = "donut",
  max,
  title,
  description,
  action,
  centerLabel = "Total",
  format,
  locales,
  thickness = 16,
  hiddenSlices,
  defaultHiddenSlices = NONE,
  onHiddenSlicesChange,
  legend = true,
  className = "",
  ...props
}: DonutChartProps) {
  const reduced = useReducedMotion();
  const gauge = variant === "gauge";
  const [ownHidden, setOwnHidden] = React.useState(defaultHiddenSlices);
  const off = hiddenSlices ?? ownHidden;
  const [active, setActive] = React.useState<string | null>(null);
  const [visible, setVisible] = React.useState(false);
  const [settled, setSettled] = React.useState(false);
  const hydrated = useHydrated();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const ringRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { rootMargin: "0px 0px -10% 0px" },
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  // Slices draw in one after another the first time only; after that every change moves them together.
  React.useEffect(() => {
    if (!visible) return;
    const timer = window.setTimeout(
      () => setSettled(true),
      900 + data.length * 90,
    );
    return () => window.clearTimeout(timer);
  }, [visible, data.length]);

  // A tap on a slice holds it; a tap anywhere else lets go.
  React.useEffect(() => {
    if (active === null) return;
    const onDown = (e: PointerEvent) => {
      if (!ringRef.current?.contains(e.target as Node)) setActive(null);
    };
    document.addEventListener("pointerdown", onDown);
    return () => document.removeEventListener("pointerdown", onDown);
  }, [active]);

  const toggle = (id: string) => {
    const shown = data.filter((s) => !off.includes(s.id)).length;
    const next = off.includes(id)
      ? off.filter((x) => x !== id)
      : shown > 1
        ? [...off, id]
        : off;
    if (next === off) return;
    if (hiddenSlices === undefined) setOwnHidden(next);
    onHiddenSlicesChange?.(next);
  };

  // Geometry: one circle, the slices laid along its stroke.
  const stroke = thickness;
  const r = SIZE / 2 - (stroke + GROW) / 2 - 1;
  const circumference = 2 * Math.PI * r;
  const span = gauge ? circumference / 2 : circumference;
  const height = gauge ? SIZE / 2 + (stroke + GROW) / 2 + 1 : SIZE;
  const centre = SIZE / 2;

  const slices = data.map((s, i) => ({
    ...s,
    color: colorOf(s, i),
    shown: !off.includes(s.id),
    amount: Math.max(0, s.value),
  }));
  const total = slices.reduce((sum, s) => sum + (s.shown ? s.amount : 0), 0);
  const fill = max && max > 0 ? Math.min(1, total / max) : 1;
  const shownCount = slices.filter((s) => s.shown && s.amount > 0).length;
  const whole = !gauge && fill >= 1 && shownCount === 1;

  const shares = slices.map((s) =>
    s.shown && total > 0 ? s.amount / total : 0,
  );
  const starts: number[] = [];
  for (let i = 0, run = 0; i < shares.length; i++) {
    starts.push(run);
    run += shares[i] * fill * span;
  }
  const arcs = slices.map((s, i) => {
    const share = shares[i];
    const length = share * fill * span;
    const start = starts[i];
    // Round caps reach past each end by half the stroke: shorten the dash so the gaps stay GAP wide.
    const drawn =
      whole && share > 0 ? circumference : Math.max(0, length - GAP - stroke);
    const at = whole
      ? 0
      : start +
        (GAP + stroke) / 2 +
        (length > 0 && length < GAP + stroke ? (length - GAP - stroke) / 2 : 0);
    return {
      ...s,
      share,
      drawn: visible ? drawn : 0,
      at,
      on: visible && share > 0,
      delay: settled ? 0 : i * 90,
    };
  });

  const current = arcs.find((a) => a.id === active && a.shown) ?? null;
  const fmt = (n: number) =>
    new Intl.NumberFormat(
      hydrated ? locales : (locales ?? "en-US"),
      format,
    ).format(n);
  const trackLength = gauge ? span - stroke : circumference;
  const turn = gauge ? 180 : -90;
  const transitionFor = (delay: number) =>
    reduced
      ? "none"
      : `stroke-dasharray 900ms ${EASE} ${delay}ms, stroke-dashoffset 900ms ${EASE} ${delay}ms, stroke-width 320ms ${EASE}, opacity 300ms ${EASE}`;
  const point = (id: string | null) => setActive(id);

  const figureSize = gauge
    ? "text-[26px] @md:text-[30px]"
    : "text-[24px] @md:text-[28px]";

  return (
    <div
      ref={rootRef}
      className={`w-full rounded-[22px] bg-background shadow-[0_0_0_1px_var(--border)] ${className}`}
      {...props}
    >
      {/* Its natural width where the parent sizes to its content (a centred flex column), without forcing it on narrow screens. */}
      <div
        aria-hidden="true"
        data-natural-width
        className="grid h-0"
        style={{ gridTemplateColumns: "minmax(0, 520px)" }}
      />
      <div className="@container w-full">
        <div className="p-4 @md:p-5">
          {(title || description || action) && (
            <div className="mb-4 flex items-start justify-between gap-3">
              <div className="min-w-0">
                {title && (
                  <p className="text-[13.5px] font-medium text-foreground @md:text-[14px]">
                    {title}
                  </p>
                )}
                {description && (
                  <p className="mt-0.5 text-[12px] text-muted-foreground @md:text-[12.5px]">
                    {description}
                  </p>
                )}
              </div>
              {action && <div className="shrink-0">{action}</div>}
            </div>
          )}

          <div
            className={`flex flex-col items-center gap-4 ${legend && !gauge ? "@lg:flex-row @lg:items-center @lg:gap-6" : ""}`}
          >
            <div
              ref={ringRef}
              className={`relative shrink-0 ${gauge ? "w-[220px] @md:w-[236px]" : "w-[176px] @md:w-[196px]"}`}
              onPointerLeave={(e) => e.pointerType === "mouse" && point(null)}
            >
              <svg
                viewBox={`0 0 ${SIZE} ${height}`}
                className="block w-full overflow-visible"
                aria-hidden="true"
              >
                <circle
                  cx={centre}
                  cy={centre}
                  r={r}
                  fill="none"
                  stroke="color-mix(in oklab, var(--foreground) 7%, transparent)"
                  strokeWidth={stroke}
                  strokeLinecap={gauge ? "round" : "butt"}
                  strokeDasharray={`${trackLength} ${circumference}`}
                  strokeDashoffset={gauge ? -stroke / 2 : 0}
                  transform={`rotate(${turn} ${centre} ${centre})`}
                />
                {arcs.map((a) => {
                  const dim = current !== null && current.id !== a.id;
                  const common = {
                    cx: centre,
                    cy: centre,
                    r,
                    fill: "none",
                    strokeLinecap: "round" as const,
                    strokeDasharray: `${a.drawn} ${circumference}`,
                    strokeDashoffset: -a.at,
                    transform: `rotate(${turn} ${centre} ${centre})`,
                  };
                  return (
                    <g key={a.id}>
                      <circle
                        {...common}
                        stroke={a.color}
                        strokeWidth={
                          current?.id === a.id ? stroke + GROW : stroke
                        }
                        style={{
                          opacity: a.on ? (dim ? 0.3 : 1) : 0,
                          transition: transitionFor(a.delay),
                        }}
                      />
                      {/* A wider, invisible copy takes the pointer, so thin slices are easy to hit. */}
                      <circle
                        {...common}
                        stroke="transparent"
                        strokeWidth={stroke + 14}
                        pointerEvents={a.on ? "stroke" : "none"}
                        className="cursor-pointer"
                        onPointerEnter={(e) =>
                          e.pointerType === "mouse" && point(a.id)
                        }
                        onClick={() => point(active === a.id ? null : a.id)}
                      />
                    </g>
                  );
                })}
              </svg>

              {/* The centre: the total, or the slice being pointed at. */}
              <div
                className={`pointer-events-none absolute inset-x-0 flex flex-col items-center text-center ${gauge ? "bottom-0" : "inset-y-0 justify-center"}`}
              >
                <span className="max-w-[70%] truncate text-[11.5px] text-muted-foreground @md:text-[12px]">
                  <TextMorph>
                    {total === 0
                      ? "No data"
                      : current
                        ? current.label
                        : centerLabel}
                  </TextMorph>
                </span>
                <span
                  className={`font-semibold leading-tight tracking-[-0.03em] text-foreground tabular-nums ${figureSize}`}
                >
                  <NumberRoll
                    value={visible ? (current ? current.amount : total) : 0}
                    format={format}
                    locales={locales}
                    duration={900}
                  />
                </span>
                <span
                  className="grid text-[11.5px] text-muted-foreground tabular-nums transition-[grid-template-rows,opacity] duration-300 @md:text-[12px]"
                  style={{
                    gridTemplateRows: current || max ? "1fr" : "0fr",
                    opacity: current || max ? 1 : 0,
                    transitionTimingFunction: EASE,
                  }}
                >
                  <span className="min-h-0 overflow-hidden">
                    {current ? (
                      <NumberRoll
                        value={current.share}
                        format={{ style: "percent" }}
                        duration={700}
                      />
                    ) : max ? (
                      <>
                        of{" "}
                        <NumberRoll
                          value={max}
                          format={format}
                          locales={locales}
                          duration={900}
                        />
                      </>
                    ) : (
                      " "
                    )}
                  </span>
                </span>
              </div>
            </div>

            {legend && (
              <ul className="w-full min-w-0 flex-1" aria-label="Slices">
                {arcs.map((a) => (
                  <li key={a.id}>
                    <button
                      type="button"
                      aria-pressed={a.shown}
                      aria-label={`${a.label}: ${fmt(a.amount)}${a.shown ? `, ${Math.round(a.share * 100)}%` : ", hidden"}`}
                      onClick={() => toggle(a.id)}
                      onPointerEnter={(e) =>
                        e.pointerType === "mouse" && point(a.id)
                      }
                      onPointerLeave={(e) =>
                        e.pointerType === "mouse" && point(null)
                      }
                      onFocus={() => point(a.id)}
                      onBlur={() => point(null)}
                      className={`flex h-9 w-full cursor-pointer items-center gap-2.5 rounded-[10px] px-2 text-left text-[12.5px] transition-[background-color,opacity] duration-200 hover:bg-accent @md:text-[13px] ${FOCUS}`}
                      style={{
                        opacity: a.shown
                          ? current && current.id !== a.id
                            ? 0.55
                            : 1
                          : 0.45,
                      }}
                    >
                      <span
                        aria-hidden="true"
                        className="size-2.5 shrink-0 rounded-full transition-[background-color,box-shadow] duration-300"
                        style={{
                          background: a.shown ? a.color : "transparent",
                          boxShadow: `inset 0 0 0 1.5px ${a.color}`,
                        }}
                      />
                      <span
                        className={`min-w-0 flex-1 truncate ${a.shown ? "text-foreground" : "text-muted-foreground line-through decoration-muted-foreground/60"}`}
                      >
                        {a.label}
                      </span>
                      <span className="tabular-nums text-foreground">
                        <NumberRoll
                          value={visible ? a.amount : 0}
                          format={format}
                          locales={locales}
                          duration={900}
                        />
                      </span>
                      <span className="w-10 text-right text-[11.5px] tabular-nums text-muted-foreground @md:text-[12px]">
                        <NumberRoll
                          value={visible ? a.share : 0}
                          format={{ style: "percent" }}
                          duration={900}
                        />
                      </span>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

